css:
.rk { font-family: Verdana, Geneva, sans-serif; color: #1c1c1c; line-height: 1.45; }
.rk, .rk p, .rk div, .rk span, .rk b, .rk td, .rk th, .rk h1, .rk h2 { font-size: 11pt !important; font-family: Verdana, Geneva, sans-serif; }
.rk h1 { font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; margin: 0; }
.rk h2 { font-weight: 700; letter-spacing: 0.03em; text-transform: uppercase; margin: 16px 0 4px 0; }
.rk .rule { border-bottom: 1px solid #333; margin: 6px 0 14px 0; }
.rk .head td { vertical-align: bottom; padding: 0 !important; }
.rk .meta { width: 100%; border-collapse: collapse; }
.rk .meta td { padding: 2px 8px 2px 0 !important; vertical-align: top; }
.rk .meta td.k { color: #555; width: 22%; }
.rk .meta td.v { border-bottom: 1px solid #e2e2e2; }
.rk table.grid { width: 100%; border-collapse: collapse; margin-top: 4px; }
.rk table.grid th { text-align: left; font-weight: 700; border-bottom: 1px solid #333; padding: 3px 6px !important; }
.rk table.grid td { border-bottom: 1px solid #e2e2e2; padding: 3px 6px !important; vertical-align: top; }
.rk .num { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }
.rk table.sum { width: 62%; margin-left: 38%; border-collapse: collapse; margin-top: 12px; }
.rk table.sum td { padding: 3px 6px !important; border-bottom: 1px solid #e2e2e2; }
.rk table.sum tr.total td { border-top: 1px solid #333; border-bottom: none; font-weight: 700; }
.rk .sign { margin-top: 36px; width: 100%; border-collapse: collapse; }
.rk .sign td { width: 45%; padding: 26px 0 0 0 !important; border-top: 1px solid #333; color: #555; }
.rk .sign td.gap { width: 10%; border: none; }
.rk .muted { color: #555; }
.rk .note { color: #666; margin-top: 6px; }
